import logging
import datetime


class AccessGatewayFilter:

    # Symbolic constants to replace magic numbers
    MAX_USER_LEVEL = 2
    JWT_VALIDITY_DAYS = 3
    DEBUG_LOG_LEVEL = 1
    JWT_DATE_FORMAT = "%Y-%m-%d"

    # Encapsulated collection for public paths
    PUBLIC_PREFIXES = ["/api", '/login']

    def __init__(self):
        pass

    def filter(self, request):
        request_uri = request['path']

        if self.is_start_with(request_uri):
            return True

        try:
            token = self.get_jwt_user(request)
            if token is None:
                return False

            user = token['user']
            if self.has_verified_access(user):
                self.set_current_user_info_and_log(user)
                return True
            return False
        except:
            return False

    def is_start_with(self, request_uri):
        return any(request_uri.startswith(prefix) for prefix in self.PUBLIC_PREFIXES)

    def get_jwt_user(self, request):
        token = request['headers']['Authorization']
        user = token['user']
        if token['jwt'].startswith(user['name']):
            jwt_str_date = token['jwt'].split(user['name'])[1]
            jwt_date = datetime.datetime.strptime(jwt_str_date, self.JWT_DATE_FORMAT)
            if datetime.datetime.today() - jwt_date >= datetime.timedelta(days=self.JWT_VALIDITY_DAYS):
                return None
        return token

    def has_verified_access(self, user):
        # Decomposed conditional / Extracted logic for clarity
        return user['level'] > self.MAX_USER_LEVEL

    def set_current_user_info_and_log(self, user):
        self.log_user_access(user)

    def log_user_access(self, user):
        host = user['address']
        timestamp = str(datetime.datetime.now())
        logging.log(msg=user['name'] + host + timestamp, level=self.DEBUG_LOG_LEVEL)
